mapper.select:
SELECT id, goods_quantity, goods_info, receipts_time, purchase_number, discount_rate, discounts_price, deposit_amount, total_amount, tax_amount, receipts_number, remake, purchase_status, file_url as receiptsAccessory, delivery_date, receipts_number FROM r_purchase_info WHERE is_deleted = 0
AND purchase_number LIKE CONCAT('%', #{params.purchaseNumber}, '%')
AND goods_info LIKE CONCAT('%', #{params.goodsInfo}, '%')
AND receipts_time >= #{params.startTime}
AND receipts_time <= #{params.endTime}
ORDER BY create_time DESC
